import React, { useState } from 'react';
import Swal from 'sweetalert2';
import './Contact.css'; // Ensure responsive design
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faInstagram } from '@fortawesome/free-brands-svg-icons';

const initialState = {
  name: '',
  mobile: '',
};

const EventRegistration = () => {
  const [{ name, mobile }, setState] = useState(initialState);
  const [registeredCount, setRegisteredCount] = useState(0); // ✅ Track count

  const handleChange = (e) => {
    const { name, value } = e.target;
    setState((prevState) => ({ ...prevState, [name]: value }));
  };

  const clearState = () => setState({ ...initialState });

  const handleSubmit = async (e) => {
    e.preventDefault();

    const formData = new FormData();
    formData.append('access_key', '26700139-3a7a-4ead-a884-383071449ce0');
    formData.append('name', name);
    formData.append('mobile', mobile);

    try {
      const response = await fetch('https://api.web3forms.com/submit', {
        method: 'POST',
        body: formData,
      });

      const result = await response.json();
      console.log(registeredCount)
      if (result.success) {
        Swal.fire({
          title: 'Success!',
          text: 'You are officially on the guest list!',
          icon: 'success',
        });
        setRegisteredCount(prev => prev + 1); // ✅ Increase count on success
        clearState();
      } else {
        Swal.fire({
          title: 'Error!',
          text: result.message || 'Something went wrong. Try again.',
          icon: 'error',
        });
      }
    } catch (error) {
      Swal.fire({
        title: 'Error!',
        text: 'Could not connect. Try again later.',
        icon: 'error',
      });
      console.error('Submission error:', error);
    }
  };

  return (
    <div id="event-registration" className="event-section">
      <div className="container">
        <h1 className="event-title">BeatXchange</h1>

        <div className='card1'>
          <h2 className="event-subtitle">2000’s vs Gen Z - Which era are you from?</h2>
        </div>

        <p className="event-description">
          Two themes, two halls - One epic party.<br />
          One pass, Unlimited vibes - Only ₹599!<br/>
          Early bird price at just ₹499!
        </p>
        <p className="event-description"></p>

        <p className="event-cta">Grab your pass to step into the Past or Future.</p>

        <div className='form-container'>
          <div className="registration-form">
            <form onSubmit={handleSubmit}>
              <div className="form-group">
                <input
                  className='in'
                  type="text"
                  name="name"
                  placeholder="Your Name"
                  required
                  value={name}
                  onChange={handleChange}
                />
              </div>
              <div className="form-group">
                <input
                  type="tel"
                  name="mobile"
                  placeholder="Your Mobile Number"
                  required
                  value={mobile}
                  onChange={handleChange}
                />
              </div>
              <button type="submit" className="register-btn small">Register</button>

              {/* ✅ Registered members count shown here */}
              
            </form>
          </div>
        </div>

        <div className="social-media">
          <h3 className='follow'>Follow Us for Event Updates</h3>
          <a
            href="https://www.instagram.com/withjayna?igsh=MXVrdXMyeW83dXFtaQ=="
            target="_blank"
            rel="noopener noreferrer"
          >
            <FontAwesomeIcon icon={faInstagram} size="2x" />
          </a>
        </div>
      </div>

      <footer id="footer">
        <div className="container text-center">
          <p>&copy; 2025 BeatXchange. All Rights Reserved.</p>
        </div>
      </footer>
    </div>
  );
};

export default EventRegistration;
